<?php get_header();rn_page_hero('OWNED PRODUCTS','自らつくり、育てるプロダクト。'); ?><section class="works-page"><div class="container"><div class="works-grid"><?php $q=new WP_Query(['post_type'=>'rn_product','posts_per_page'=>-1,'orderby'=>'menu_order','order'=>'ASC']);while($q->have_posts()):$q->the_post(); ?><article class="product-card"><a href="<?php the_permalink(); ?>"><?php if(has_post_thumbnail()){the_post_thumbnail('rnstyle-work');} ?><h2><?php the_title(); ?></h2><?php the_excerpt(); ?></a></article><?php endwhile;if(!$q->found_posts){echo '<p>プロダクト情報は準備中です。</p>';}wp_reset_postdata(); ?></div><?php while(have_posts()):the_post();the_content();endwhile; ?></div></section><?php get_template_part('template-parts/cta');get_footer(); ?>
